codeRecipes.beforeCode:
// ❌ Mutate trực tiếp Object & Gọi setState liên tiếp không dùng prev
function Counter() {
  const [user, setUser] = useState({ name: 'Nam', age: 25 });
  const handleHappyBirthday = () => {
    user.age += 1; // ❌ Mutate trực tiếp! React không nhận ra thay đổi
    setUser(user);
  };
}

codeRecipes.afterCode:
// ✅ Tạo Object mới với Spread Operator & Functional Updater
function Counter() {
  const [user, setUser] = useState({ name: 'Nam', age: 25 });
  const handleHappyBirthday = () => {
    setUser((prevUser) => ({
      ...prevUser,
      age: prevUser.age + 1
    }));
  };
  return <button onClick={handleHappyBirthday}>Tuổi: {user.age}</button>;
}

