function TodoList({ items }: { items: Todo[] }) {
  return (
    <div>
      {/* Nếu items rỗng, sẽ in ra số 0 trên màn hình! */}
      {items.length && <span>Có {items.length} công việc</span>}
      {items.map((item, idx) => (
        <TodoItem key={idx} todo={item} /> // ❌ Dễ gây lỗi state khi xóa/sort
      ))}
    </div>
  );
}

codeRecipes.afterCode:
// ✅ Dùng unique item.id và điều kiện Boolean an toàn
function TodoList({ items }: { items: Todo[] }) {
  return (
    <div>
      {items.length > 0 ? <span>Có {items.length} công việc</span> : null}
      {items.map((item) => (
        <TodoItem key={item.id} todo={item} /> // ✅ Key ổn định và duy nhất
      ))}
    </div>
  );
}
